{
  "faithfulness": 1,
  "citation_correctness": 1,
  "citation_completeness": 1,
  "unsupported_claims": [
    {
      "claim_id": "L005",
      "reason": "States that 20 h ROM is a significant driver and contributes 50% risk, but NICE source (S012, S013) specifies risk increase only for >24 h; no evidence for 20 h."
    },
    {
      "claim_id": "L008",
      "reason": "Assigns point values (2 points) to ROM 20 h and CRP 12 mg/L without any source providing such scoring."
    },
    {
      "claim_id": "L019",
      "reason": "Recommends cefotaxime substitution for ampicillin based on non‑severe penicillin allergy, but source S016 only mentions cefotaxime plus metronidazole for non‑severe allergy; the plan does not cite this source."
    },
    {
      "claim_id": "L021",
      "reason": "Suggests IV clindamycin as default for penicillin allergy, yet no provided passage (S016) recommends clindamycin; it recommends cefotaxime or vancomycin."
    },
    {
      "claim_id": "L022",
      "reason": "Specifies duration 48‑72 h and stop criteria referencing NICE recommendation 1.21.3, but the cited passages (S015) only note that the recommendation wording changed, not the exact duration or stop criteria."
    }
  ],
  "contradictions": [],
  "ungrounded_dose": false,
  "ungrounded_dose_examples": [],
  "rationale": "Most plan statements are not directly supported by the supplied NICE passages. The risk assessment uses a 20 h ROM threshold contrary to the >24 h threshold in S012/S013. Scoring points and specific antibiotic choices (clindamycin) lack source backing. Citation mapping is absent, leading to low citation correctness and completeness. No numeric dose is presented, so no ungounded dose issue."
}
